import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

interface ValidationError {
  keyword: string;
  params?: {missingProperty?: unknown};
  instancePath?: string;
  dataPath?: string;
  message?: string;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validator = new Ajv({strict: false, validateFormats: false} as never);
  private readonly dynamicValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.validator.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid input schema for tool ${resolved.name}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  private validatorFor(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
    if (tool.validator) return tool.validator;
    const cached = this.dynamicValidators.get(definition.inputSchema);
    if (cached) return cached;
    const validator = this.validator.compile(definition.inputSchema);
    this.dynamicValidators.set(definition.inputSchema, validator);
    return validator;
  }

  private validationResult(error?: ValidationError | null): string {
    if (!error) return 'Tool input validation failed.';
    if (error.keyword === 'required') {
      const missingProperty = (error.params as {missingProperty?: unknown} | undefined)?.missingProperty;
      const parentPath = error.instancePath || '';
      return `Tool input validation failed: ${parentPath}/${this.jsonPointerToken(missingProperty)} is required`;
    }
    const propertyPath = error.instancePath || this.pointerFromDataPath(error.dataPath) || '/';
    return `Tool input validation failed: ${propertyPath} ${error.message ?? 'is invalid'}`;
  }

  private pointerFromDataPath(dataPath?: string): string | undefined {
    if (!dataPath) return undefined;
    return dataPath.replace(/\[([0-9]+)\]/g, '/$1').replace(/\.([^.[\]]+)/g, '/$1');
  }

  private jsonPointerToken(value: unknown): string {
    return String(value ?? '')
      .replace(/~/g, '~0')
      .replace(/\//g, '~1');
  }

  /** Executes a tool; see specs/hal-engine-tool-input-validation/spec.md for input-validation failures. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = this.validatorFor(tool, definition);
    if (!validate(input)) {
      return {result: this.validationResult(validate.errors?.[0] as ValidationError | undefined)};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {jest} from '@jest/globals';
import {ToolRegistry, type ToolExecutor} from './registry.js';
import {registerWeatherTool} from './registry.test-support.js';

function registerTool(registry: ToolRegistry, inputSchema: Record<string, unknown>, execute: ToolExecutor): void {
  registry.register(
    {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema,
    },
    execute
  );
}

async function expectRejection(
  registry: ToolRegistry,
  execute: ToolExecutor,
  input: Record<string, unknown>,
  result: string
): Promise<void> {
  await expect(registry.execute('get_weather', input)).resolves.toEqual({result});
  expect(execute).not.toHaveBeenCalled();
}

describe('ToolRegistry input validation', () => {
  it('names the property path and expected type when rejecting a wrong-typed field', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'unreachable');
    registerWeatherTool(registry, execute);

    await expectRejection(registry, execute, {location: 42}, 'Tool input validation failed: /location must be string');
  });

  it('reports the full nested path for a missing required property', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'unreachable');
    registerTool(
      registry,
      {
        type: 'object',
        properties: {
          request: {
            type: 'object',
            properties: {location: {type: 'string'}},
            required: ['location'],
          },
        },
        required: ['request'],
      },
      execute
    );

    await expectRejection(
      registry,
      execute,
      {request: {}},
      'Tool input validation failed: /request/location is required'
    );
  });

  it('reports required property names using escaped JSON Pointer tokens', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'unreachable');
    registerTool(
      registry,
      {
        type: 'object',
        properties: {'city/name': {type: 'string'}},
        required: ['city/name'],
      },
      execute
    );

    await expectRejection(registry, execute, {}, 'Tool input validation failed: /city~1name is required');
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L17)).
- When a nested object omits a required property, the rejection names the full JSON Pointer path to that property ([validated by: reports the full nested path for a missing required property](../../src/orchestration/tools/registry.test.ts#L35)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L36), [validated by: names the property path and expected type when rejecting a wrong-typed field](../../src/orchestration/tools/registry.test.ts#L27)).
- When a validator reports a property path, the rejection names it using JSON Pointer notation; required property names with JSON Pointer-reserved characters are escaped as tokens ([validated by: reports required property names using escaped JSON Pointer tokens](../../src/orchestration/tools/registry.test.ts#L62)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L84)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules.

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L102)).
